(function(root){
 const alphabet='abcdefghijklmnopqrstuvwxyz'.split('');
 const pictures={a:{word:'apple',cell:0},b:{word:'ball',cell:1},c:{word:'cat',cell:2},d:{word:'dog',cell:3},f:{word:'fish',cell:4},h:{word:'hat',cell:5},m:{word:'map',cell:6},p:{word:'pig',cell:7},s:{word:'sun',cell:8},t:{word:'top',cell:9},u:{word:'umbrella',cell:10},v:{word:'van',cell:11}};
 const thresholds=[5,10,15,20,26];
 const mix=(a,rng=Math.random)=>a.map(v=>({v,k:rng()})).sort((a,b)=>a.k-b.k).map(x=>x.v);
 const key=q=>q.id||q.letter+':'+q.mode;
 const events=(run,q)=>run.answers.filter(e=>e.questionKey===key(q));
 function options(letter,task,difficulty,rng){const pool=task==='picture'?Object.keys(pictures):alphabet;const compatible=pool.filter(l=>l!==letter&&!(task!=='name'&&['c','k'].includes(letter)&&['c','k'].includes(l)));const groups=['bpdt','mn','fvsz','cgkq','aeiou','rlyw'];const similar=groups.find(g=>g.includes(letter))||'';const ordered=difficulty==='challenge'?[...mix(compatible.filter(l=>similar.includes(l)),rng),...mix(compatible.filter(l=>!similar.includes(l)),rng)]:mix(compatible,rng);return mix([letter,...ordered.slice(0,2)],rng);}
 function makeItem(letter,mode,index,difficulty,rng){let task='name';if(mode==='sound'){if(pictures[letter])task=difficulty==='gentle'?(index%2?'word':'letter'):['picture','audio','word','letter'][index%4];else task=difficulty==='gentle'?'letter':index%2?'audio':'letter';}return {letter,mode,task,options:options(letter,task,difficulty,rng)};}
 function create(difficulty='explorer',rng=Math.random){const names=alphabet.map((l,i)=>makeItem(l,'name',i,difficulty,rng));let sounds=mix(alphabet,rng);if(sounds[0]==='z')sounds.push(sounds.shift());const soundItems=sounds.map((l,i)=>makeItem(l,'sound',i,difficulty,rng));if(difficulty!=='gentle'){const pictured=soundItems.filter(q=>pictures[q.letter]);pictured[0].task='picture';pictured[1].task='word';const auditory=soundItems.find(q=>!pictures[q.letter]);auditory.task='audio';for(const q of soundItems)q.options=options(q.letter,q.task,difficulty,rng);}return {type:'diagnostic',schemaVersion:4,kind:'diagnostic',difficulty,index:0,startedAt:new Date().toISOString(),answers:[],items:[...names,...soundItems]};}
 function practice(report,onlyLetter,rng=Math.random){const targets=report.detail.filter(d=>(!onlyLetter||d.letter===onlyLetter)&&(d.name.errors.length||d.sound.errors.length));const items=[];for(const d of targets){for(const mode of ['name','sound']){if(!d[mode].errors.length)continue;for(let i=0;i<2;i++){const q=makeItem(d.letter,mode,i,'explorer',rng);if(mode==='sound'){q.task=pictures[d.letter]?(i===0?'picture':'audio'):(i===0?'audio':'letter');q.options=options(d.letter,q.task,'explorer',rng);}q.id='practice:'+d.letter+':'+mode+':'+i;items.push(q);}}}return {type:'diagnostic',schemaVersion:4,kind:'practice',difficulty:'explorer',index:0,startedAt:new Date().toISOString(),answers:[],items:mix(items,rng),sourceAt:report.at};}
 function answer(run,selected,heard){const q=run.items[run.index];if(!q||!heard||!q.options.includes(selected))return {accepted:false};const prior=events(run,q);if(prior.some(e=>e.correct)||prior.some(e=>!e.correct&&e.answer===selected))return {accepted:false};const event={questionKey:key(q),letter:q.letter,mode:q.mode,task:q.task,answer:selected,correct:selected===q.letter,attempt:prior.length+1,questionIndex:run.index,at:new Date().toISOString()};run.answers.push(event);return {accepted:true,correct:event.correct,event};}
 function progress(run){
  if(run.kind==='practice'){const answered=run.items.filter(q=>events(run,q).some(e=>e.correct)).length;return {answered,total:run.items.length,percent:Math.round(answered/run.items.length*100),remainingQuestions:run.items.length-answered};}
  const report=root.AssessmentCore.summarize(run),solved=new Set(),completionOrder=[];
  for(const e of run.answers){if(!e.correct)continue;solved.add(e.letter+':'+e.mode);if(solved.has(e.letter+':name')&&solved.has(e.letter+':sound')&&!completionOrder.includes(e.letter))completionOrder.push(e.letter);}
  let streak=0,series=[],milestones=[];
  for(const letter of completionOrder){const d=report.detail.find(x=>x.letter===letter);if(d.name.firstTry&&d.sound.firstTry){series.push(letter);streak++;if(thresholds.includes(streak))milestones.push({key:run.startedAt+':'+series[0]+':tier:'+streak,threshold:streak,letters:series.slice(),endingLetter:letter});}else{series=[];streak=0;}}
  const current=run.items[run.index];if(current&&!completionOrder.includes(current.letter)&&run.answers.some(e=>e.letter===current.letter&&!e.correct)){streak=0;}
  const answered=run.items.filter(q=>events(run,q).some(e=>e.correct)).length,next=thresholds.find(t=>t>streak)||26;
  return {completed:completionOrder.length,answered,total:52,remainingLetters:26-completionOrder.length,remainingQuestions:52-answered,percent:Math.round(answered/52*100),streak,nextThreshold:next,nextReward:Math.max(0,next-streak),milestones,letters:report.detail.map(d=>({...d,problem:!!(d.name.errors.length||d.sound.errors.length),complete:d.name.completed&&d.sound.completed}))};
 }
 root.GameCore={create,practice,answer,events,key,progress,pictures,thresholds};
})(globalThis);
